import json
Q=[]
def q(n,ru,kk,ropts,kopts=None,**kw):
    d={'n':n,'ru':{'q':ru,'opts':ropts},'kk':{'q':kk,'opts':kopts if kopts is not None else ropts}}; d.update(kw); Q.append(d)
q(1,r"За месяц Данияр прошёл 24 уровня игры «Archero», что составляло \(\tfrac4{15}\) всех уровней. Сколько всего уровней в игре?",r"Бір айда Данияр «Archero» ойынының 24 деңгейін өтті, бұл барлық деңгейлердің \(\tfrac4{15}\) бөлігін құрады. Ойында барлығы қанша деңгей бар?",["84","90","91","98"])
q(2,"Труба A наполняет бассейн за 6 часов. А трубы (водостоки) B и C опустошают полный бассейн за 12 и 24 часов соответственно. Все три трубы были открыты на протяжении 6 часов, затем B и C закрыли. За какое время труба A заполнит оставшуюся часть бассейна?","A құбыры бассейнді 6 сағатта толтырады. Ал B және C құбырлары (су ағызғыштар) толық бассейнді сәйкесінше 12 және 24 сағатта босатады. Үш құбыр да 6 сағат бойы ашық болды, содан кейін B және C жабылды. A құбыры бассейннің қалған бөлігін қанша уақытта толтырады?",["1 час","3 часа","4 часа","другой ответ"],["1 сағат","3 сағат","4 сағат","басқа жауап"])
q(3,"В первый день кладоискатели нашли две части сокровища, во второй — одну часть, а в третий — четыре части клада. Какое количество клада они нашли в третий день, если всё сокровище составило 504 золотых песо.","Бірінші күні қазына іздеушілер қазынаның екі бөлігін, екінші күні бір бөлігін, ал үшінші күні қазынаның төрт бөлігін тапты. Бүкіл қазына 504 алтын песо болса, олар үшінші күні қанша қазына тапты.",["144","216","288","72"])
